import org.junit.jupiter.api.io.TempDir;

class LmdbCorrelatedFiniteSurfaceEstimatorTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void correlatedRelationPreservesMultiColumnTuplePairing(@TempDir File dataDir) throws Exception {
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			IRI firstSubject = VF.createIRI("urn:test:correlated:first-subject");
			IRI secondSubject = VF.createIRI("urn:test:correlated:second-subject");
			IRI firstPredicate = VF.createIRI("urn:test:correlated:first-predicate");
			IRI secondPredicate = VF.createIRI("urn:test:correlated:second-predicate");
			try (var connection = repository.getConnection()) {
				connection.add(firstSubject, firstPredicate, VF.createIRI("urn:test:correlated:first-object"));
				connection.add(secondSubject, secondPredicate, VF.createIRI("urn:test:correlated:second-object"));
				for (int index = 0; index < 10; index++) {
					connection.add(firstSubject, secondPredicate,
							VF.createIRI("urn:test:correlated:cross-a:" + index));
					connection.add(secondSubject, firstPredicate,
							VF.createIRI("urn:test:correlated:cross-b:" + index));
				}
			}

			Map<List<Value>, Double> pairs = new LinkedHashMap<>();
			pairs.put(List.of(firstSubject, firstPredicate), 1.0d);
			pairs.put(List.of(secondSubject, secondPredicate), 1.0d);
			FiniteRelationEstimate relation = FiniteRelationEstimate.fromFrequencies(
					List.of("subject", "predicate"), pairs, "frontier-correlation");
			StatementPattern accessKernel = new StatementPattern(
					Var.of("subject"), Var.of("predicate"), Var.of("object"));

			Object runtime = ((LmdbEvaluationStatistics) store.getBackingStore().getEvaluationStatistics())
					.estimatorRuntime();
			var method = runtime.getClass()
					.getDeclaredMethod("exactCorrelatedSurface", FiniteRelationEstimate.class,
							org.eclipse.rdf4j.query.algebra.TupleExpr.class);
			method.setAccessible(true);
			Optional<?> estimated = (Optional<?>) method.invoke(runtime, relation, accessKernel);
			assertTrue(estimated.isPresent());
			Object surface = estimated.orElseThrow();
			assertEquals(2.0d, number(surface, "surfaceRows"));
			assertEquals(2.0d, number(surface, "prefixRows"));
			assertEquals(2.0d, number(surface, "scannedRows"));
		} finally {
			repository.shutDown();
		}
	}

	private static double number(Object target, String accessor) throws Exception {
		var method = target.getClass().getDeclaredMethod(accessor);
		method.setAccessible(true);
		return ((Number) method.invoke(target)).doubleValue();
	}
}
